'use strict';
const $=s=>document.querySelector(s),E=Economy,KEY='new-formosa-life-v3';const money=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:2}),fmt=money;
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));const old=JSON.parse(localStorage.getItem('new-formosa-v1')||'{}');state=saved?.version===3?saved:E.initial(old||{});}catch{state=E.initial();}
let page='home',tavernGame='bingo',bingoMode='basic',bingoNumbers=[],lottoNumbers=[],bingoStake=10,selectedCity=state.city||'臺北市',cityRegion='all',toastTimer,order=null,spinning=false;
const NAV=[['home','⌂','我的生活'],['jobs','▣','尋找工作'],['tavern','♧','巷口酒館'],['shop','▤','生活商店'],['auction','⚑','拍賣行'],['stocks','↗','寶島股市']];
function icon(k){const label={cash:'NT$',xp:'EXP',tax:'稅',gold:'G',energy:'ϟ'};return `<span class="resource-icon ${k}" aria-hidden="true">${label[k]}</span>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('無法儲存進度，請確認裝置儲存空間');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(html){$('#modal').classList.remove('map-dialog');$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function clock(ms){let n=Math.max(0,Math.ceil(ms/1000));const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return (h?h.toString().padStart(2,'0')+':':'')+m.toString().padStart(2,'0')+':'+s.toString().padStart(2,'0');}
function stamp(t){return new Date(t).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function title(k,t,right=''){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${t}</h1></div>${right}</div>`;}
function header(){E.energy(state,Date.now());$('#resources').innerHTML=`<button class="resource" data-action="wallet" aria-label="新台幣 ${money(state.cash)}">${icon('cash')} ${money(state.cash)}</button><button class="resource premium" data-action="gold" aria-label="黃金 ${state.premium}">${icon('gold')} ${state.premium}</button><button class="resource" data-action="stamina" aria-label="體力 ${state.energy} / 100">${icon('energy')} ${state.energy}/100 <b>＋</b></button>`;$('#level').textContent=1+Math.floor(state.exp/500);}
function cityLevel(){return (CITY_INFO.find(c=>c.name===state.city)?.level||1)+Math.floor(state.donated/300);}
function currentJob(){if(state.job){const j=state.job,info=E.JOBS[j.job],progress=Math.min(100,(Date.now()-j.start)/(j.end-j.start)*100);return `<div class="active-job"><img src="assets/${info[2]}.png" alt="${info[0]}職人"><div><span class="badge">工作進行中</span><h3>${info[0]}</h3><p>完成後領取 ${icon('cash')} <b>${money(j.rate*j.minutes)}</b></p><div class="progress"><i data-job-progress style="width:${progress}%"></i></div><span class="muted">剩餘 <b data-until="${j.end}">${clock(j.end-Date.now())}</b> · 離線也會完成</span></div></div>`;}
if(state.jobResult){const r=state.jobResult;return `<section class="job-result"><span class="badge">工作完成 · 已自動入帳</span><h3>辛苦了，今天又前進一步！</h3><p>${icon('cash')} 新台幣 +${money(r.pay)} · ${icon('xp')} 社會歷練 +${r.stars*r.minutes*5}</p><p class="muted">工作小物：${r.drops.length?r.drops.map(id=>E.ITEMS.find(x=>x.id===id).name).join('、'):'這次沒有額外小物'}</p><button class="btn gold" data-action="next-jobs">看看新的三份工作 ›</button></section>`;}return '';}
function home(){return `${title('A LITTLE LIFE IN FORMOSA','寶島生活日常',`<span class="badge">${state.city||'尚未選擇家鄉'}</span>`)}<section class="hero life-hero"><img src="assets/world.png" alt="Q版台灣海島小鎮"><div class="hero-copy"><span class="badge">${state.city?'我的家鄉 · '+state.city:'22 縣市，選一個家'}</span><h2>在寶島，好好過日子。</h2><p>找份工作、逛逛小店，偶爾到巷口坐坐。</p><button class="btn gold" data-page="jobs">${state.job?'查看目前工作':'找一份好工作'} ›</button> <button class="btn map-open" data-action="choose">探索台灣地圖</button></div></section><div class="life-summary"><div>${icon('cash')}<span>生活存款<b>${money(state.cash)}</b></span></div><div>${icon('energy')}<span>今日體力<b>${state.energy}<small> / 100</small></b></span></div><div>${icon('xp')}<span>社會歷練<b>${money(state.exp)}</b></span></div><div>${icon('tax')}<span>納稅額度<b>${money(state.tax)}</b></span></div></div>${currentJob()}<div class="district-grid"><button class="district work" data-page="jobs"><span class="district-icon">▣</span><span class="eyebrow">WORK & EARN</span><h3>尋找工作</h3><p>三份機會，選一份適合你的。</p><b>查看工作 ›</b></button><button class="district pub" data-page="tavern"><span class="district-icon">♧</span><span class="eyebrow">AFTER HOURS</span><h3>巷口酒館</h3><p>賓果、大樂透，還有餃子老虎雞。</p><b>進去坐坐 ›</b></button><button class="district market" data-page="stocks"><span class="district-icon">↗</span><span class="eyebrow">FORMOSA EXCHANGE</span><h3>寶島股市</h3><p>五檔虛構股票，每小時新行情。</p><b>查看行情 ›</b></button></div><div class="life-bottom"><section class="panel"><div class="section-heading"><h3>我的隨身小物</h3><button class="text-btn" data-page="shop">前往商店 ›</button></div><p class="muted">工作完成後可能取得小物，可在商店出售。</p><div class="mini-inventory">${E.ITEMS.filter(i=>state.inventory[i.id]).map(i=>`<span>${i.icon} ${i.name} ×${state.inventory[i.id]}</span>`).join('')||'<span>背包還空著，先去接份工作吧。</span>'}</div></section><section class="panel"><h3>最近的生活紀錄</h3>${ledger(4)}</section></div><div class="notice">本機生活模擬 · 新台幣為不可兌現遊戲資源 · 城市人數與市場非真實資料</div>`;}
function ledger(n){return `<div class="ledger">${state.ledger.slice(0,n).map(x=>`<div><span>${x.text}<small>${stamp(x.at)}</small></span><b class="${x.delta>=0?'positive':'negative'}">${x.delta>0?'+':''}${x.delta?money(x.delta):'—'}</b></div>`).join('')||'<p class="muted">還沒有紀錄，新的生活正要開始。</p>'}</div>`;}
function jobs(){return `${title('FIND YOUR NEXT SHIFT','尋找工作',`<span class="badge">體力 ${state.energy} / 100</span>`)}<p class="section-intro">系統隨機派發三份工作。選好工作時長，準時完成就能領薪水。</p>${currentJob()}${!state.job&&!state.jobResult?`<div class="jobs-grid">${state.offers.map(o=>{const j=E.JOBS[o.job];return `<article class="job-card"><div class="job-portrait"><img src="assets/${j[2]}.png" alt="${j[0]}的動物職人"><span class="job-stars">${'★'.repeat(o.stars)}${'☆'.repeat(5-o.stars)}</span></div><div class="job-card-body"><span class="eyebrow">${o.stars} 星工作 · 在地職缺</span><h2>${j[0]}</h2><p>${j[1]}</p><div class="job-rate"><span>${icon('cash')}<b>${o.rate}</b><small>/ 分鐘</small></span><span>${icon('energy')}<b>${o.energy}</b><small>/ 分鐘</small></span></div><label class="field-label">工作時長<select data-minutes="${o.uid}">${[1,5,10,30].map(m=>`<option value="${m}" ${m*o.energy>state.energy?'disabled':''}>${m} 分鐘 · ${money(m*o.rate)} 新台幣 / ${m*o.energy} 體力</option>`).join('')}</select></label><button class="btn gold full" data-accept="${o.uid}" ${state.energy<o.energy?'disabled':''}>接下這份工作 ›</button></div></article>`;}).join('')}</div>`:''}<div class="work-notes"><span>① 選擇三份工作之一</span><span>② 一次扣除所需體力</span><span>③ 時間到自動結算薪資與小物</span></div><p class="muted">每次只可進行一份工作，完成並確認後派發新的三份。星等越高，每分鐘薪資與消耗越高。體力每 5 分鐘恢復 1 點，上限 100。</p>`;}
function tavern(){return `${title('THE CORNER TAVERN','巷口酒館',`<span class="badge">純遊戲娛樂 · 無現金獎品</span>`)}<div class="tavern-heading"><div><span class="eyebrow">今晚，想玩哪一桌？</span><h2>工作結束，來坐一下。</h2><p>只使用遊戲賺取的新台幣；黃金無法兌換遊戲籌碼或彩金。</p></div><span class="tavern-sign">酒<br>館</span></div><div class="game-tabs">${[['bingo','BINGO','賓果賓果','每 5 分鐘'],['lotto','LOTTO','寶島大樂透','每 12 小時'],['slots','LUCKY LINE','餃子老虎雞','三格連線']].map(([id,en,n,time])=>`<button data-game="${id}" class="${tavernGame===id?'selected':''}"><small>${en}</small><b>${n}</b><span>${time}</span></button>`).join('')}</div>${tavernGame==='slots'?slotView():lotteryView(tavernGame)}`;}
function lotteryView(type){const isB=type==='bingo',r=E.round(type),last=E.draw(type,r.id-1,state.seed),selected=isB?bingoNumbers:lottoNumbers,max=isB?80:49,showNumbers=!isB||['basic','super'].includes(bingoMode);return `<section class="draw-clock"><div><span class="badge">第 ${r.id} 期</span><h3>${isB?'下一期賓果開獎':'下一期大樂透開獎'}</h3><p>${stamp(r.end)}（台灣時間）</p></div><b data-until="${r.end}">${clock(r.end-Date.now())}</b></section><div class="lottery-layout"><section class="panel number-panel">${isB?`<div class="bingo-modes">${[['basic','基本選號'],['super','超級獎號'],['small','猜小'],['big','猜大'],['odd','猜單'],['even','猜雙']].map(([id,n])=>`<button data-mode="${id}" class="${bingoMode===id?'active':''}">${n}</button>`).join('')}</div>`:''}<div class="section-heading"><h3>${isB?bingoMode==='basic'?'選 1～10 個號碼':bingoMode==='super'?'預測第 20 個獎號':'預測 20 個開出號碼的分布':'從 01～49 選 6 個號碼'}</h3>${showNumbers?`<button class="text-btn" data-action="quick-pick">電腦選號 ↻</button>`:''}</div>${showNumbers?`<div class="number-grid">${Array.from({length:max},(_,i)=>i+1).map(n=>`<button data-number="${n}" aria-pressed="${selected.includes(n)}" class="${selected.includes(n)?'picked':''}">${String(n).padStart(2,'0')}</button>`).join('')}</div>`:`<div class="prediction"><b>${({small:'01～40 至少 13 個',big:'41～80 至少 13 個',odd:'單數至少 13 個',even:'雙數至少 13 個'})[bingoMode]}</b><p>符合條件即得投入金額的 5 倍。未達 13 個則不獲獎。</p></div>`}</section><aside class="ticket-slip"><span class="eyebrow">MY PLAY SLIP</span><h3>${isB?'賓果選號單':'大樂透選號單'}</h3><div class="selected-balls">${showNumbers?(selected.length?selected.map(n=>`<b>${String(n).padStart(2,'0')}</b>`).join(''):'<span>從左側選擇號碼</span>'):`<b class="word-ball">${({small:'猜小',big:'猜大',odd:'猜單',even:'猜雙'})[bingoMode]}</b>`}</div><div class="slip-row"><span>選號數量</span><b>${showNumbers?selected.length:'分布預測'}</b></div><label class="field-label">${isB?'投入遊戲新台幣':'每注遊戲新台幣'}${isB?`<select id="bingo-stake">${[10,50,100].map(n=>`<option value="${n}" ${n===bingoStake?'selected':''}>${n}</option>`).join('')}</select>`:'<b class="fixed-price">50</b>'}</label><button class="btn gold full" data-action="place-ticket" ${(!isB&&selected.length!==6)||(isB&&showNumbers&&!selected.length)||state.cash<(isB?bingoStake:50)?'disabled':''}>確認參加 · NT$ ${isB?bingoStake:50}</button><p class="muted">彩金為遊戲資源，不能兌現。開獎後自動入帳，離線期間的選號會在下次開啟時結算。</p></aside></div><section class="panel draw-results"><div class="section-heading"><h3>上一期開獎</h3><span class="muted">第 ${r.id-1} 期 · 本機模擬</span></div><div class="result-balls">${last.numbers.map(n=>`<span>${String(n).padStart(2,'0')}</span>`).join('')}<b>${isB?'超級獎號':'特別號'}</b><span class="special">${String(isB?last.super:last.special).padStart(2,'0')}</span></div></section><div class="lottery-bottom"><section class="panel"><h3>我的參加紀錄</h3>${ticketHistory(type)}</section><section class="panel rules-panel"><h3>遊戲規則與獎勵</h3>${isB?bingoRules():lottoRules()}</section></div>`;}
function bingoRules(){return `<p>每 5 分鐘從 01～80 開出 20 個不重複號碼，第 20 個為超級獎號。基本玩法可選 1～10 號，選號數即星數。</p><p>超級獎號猜中得 50 倍；猜大小／單雙需對應號碼至少 13 個，得 5 倍。所有倍數均為含本金的總彩金。</p><details><summary>基本玩法完整倍率表</summary><table class="rules-table"><thead><tr><th>選幾號</th><th>命中數：總彩金倍數</th></tr></thead><tbody>${Object.entries(E.BINGO_PAY).map(([n,p])=>`<tr><td>${n} 星</td><td>${Object.entries(p).map(([hits,m])=>`${hits} 中：${m} 倍`).join(' / ')}</td></tr>`).join('')}</tbody></table></details><p class="muted">未列組合不獲獎。此為寶島自訂獎勵，並非台灣彩券官方賠率。</p>`;}
function lottoRules(){return `<p>從 01～49 選 6 號，開出 6 個主號及 1 個不重複特別號。每日台灣時間 00:00、12:00 開獎。每注 50。</p><table class="rules-table"><thead><tr><th>獎項</th><th>命中條件</th><th>遊戲彩金</th></tr></thead><tbody>${[['頭獎','6 主號','10,000,000'],['貳獎','5 主號＋特別','1,000,000'],['參獎','5 主號','100,000'],['肆獎','4 主號＋特別','10,000'],['伍獎','4 主號','2,000'],['陸獎','3 主號＋特別','1,000'],['柒獎','2 主號＋特別','400'],['普獎','3 主號','400']].map(a=>`<tr>${a.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="muted">採固定遊戲彩金，不採現實彩券的浮動獎池；每注只領最高符合獎項。</p>`;}
function ticketHistory(type){const tickets=state.tickets.filter(t=>t.type===type).slice(-8).reverse();return `<div class="ticket-history">${tickets.map(t=>`<article><div><b>第 ${t.round} 期</b><span class="badge">${t.status==='pending'?'等待開獎':t.award.tier}</span></div><p>${t.numbers.length?t.numbers.map(n=>String(n).padStart(2,'0')).join(' · '):({small:'猜小',big:'猜大',odd:'猜單',even:'猜雙'})[t.mode]}</p><small>投入 ${money(t.stake)}${t.status==='settled'?' · 彩金 '+money(t.award.prize)+'（已結算）':' · '+stamp(t.end)}</small></article>`).join('')||'<p class="muted">這一桌還沒有參加紀錄。</p>'}</div>`;}
function slotView(){const s=state.lastSlots;return `<section class="slot-machine"><span class="badge">LUCKY LINE · 三格同圖連線</span><h2>餃子・老虎・雞</h2><div class="slot-reels ${spinning?'spinning':''}">${(s?.reels||['🥟','🐯','🐔']).map(x=>`<span>${x}</span>`).join('')}</div><div class="slot-status" aria-live="polite">${spinning?'轉動中…':s?s.prize?`連線成功！${s.mult} 倍 · 彩金 ${money(s.prize)}`:'這次未連線。可以回去工作累積收入。':'三個相同圖案，即可獲得對應遊戲彩金。'}</div><button class="btn gold" data-action="spin" ${spinning||state.cash<50?'disabled':''}>${spinning?'轉動中…':'轉動一次 · NT$ 50'}</button></section><section class="panel slot-rules"><h3>連線規則</h3><p class="muted">每格獨立從 8 種圖案等機率抽出；只判定中間一條橫線，三格必須相同。總連線機率 1/64，每種指定三連機率 1/512。</p><div class="slot-pay">${[['🥟',60],['🐯',120],['🐔',40],['🍵',20],['🧧',30],['🍍',20],['🏮',20],['⭐',10]].map(([i,m])=>`<div><b>${i}${i}${i}</b><span>${m} 倍</span></div>`).join('')}</div><p class="muted">倍數為含本金總彩金；未連線為 0。不可用黃金參加、不能兌現。</p></section>`;}
function shop(){return `${title('THE NEIGHBORHOOD STORE','寶島生活商店')}<div class="shop-banner"><span class="badge">日常用品 · 小物回收 · 一番賞</span><h2>補點元氣，再繼續出發。</h2><p>買份便當存進背包，也把工作的小收穫換成生活費。</p></div><div class="section-heading shop-section"><h2>元氣補給</h2><button class="text-btn" data-action="stamina">查看體力 ›</button></div><div class="goods-grid">${E.GOODS.map(g=>`<article class="panel goods-card"><span class="goods-icon">${g.icon}</span><h3>${g.name}</h3><p>${g.desc}</p><span class="badge">體力 +${g.energy}</span><div class="goods-actions"><button class="btn gold" data-buy="${g.id}" ${state.cash<g.price?'disabled':''}>購買 · ${g.price}</button><button class="btn light" data-use="${g.id}" ${!state.food[g.id]||state.energy+g.energy>100?'disabled':''}>使用（${state.food[g.id]||0}）</button></div></article>`).join('')}</div><section class="panel shop-section"><div class="section-heading"><h2>工作小物回收</h2><span class="muted">每次出售 1 件</span></div><div class="sell-grid">${E.ITEMS.map(i=>`<div class="sell-row"><span class="item-symbol">${i.icon}</span><div><b>${i.name}</b><small>持有 ${state.inventory[i.id]||0} 件</small></div><button class="btn light" data-sell="${i.id}" ${!state.inventory[i.id]?'disabled':''}>售出 +${i.sell}</button></div>`).join('')}</div></section><section class="ichiban shop-section"><div><span class="eyebrow">FORMOSA SOUVENIRS</span><h2>寶島生活一番賞</h2><p>每次 200 遊戲新台幣，隨機獲得一件紀念小物。</p><button class="btn gold" data-action="ichiban" ${state.cash<200?'disabled':''}>抽一次 · NT$ 200</button><p class="muted">每抽獨立，無限獎池；不同於實體有限籤的一番賞。<br>不消耗黃金，無現金獎品。</p></div><div class="prize-grid">${E.PRIZES.map(p=>`<div><span>${p.icon}</span><b>${p.name}</b><small>${p.weight}% · 持有 ${state.collectibles[p.id]||0}</small><button class="text-btn" data-sell-prize="${p.id}" ${!state.collectibles[p.id]?'disabled':''}>出售 1 件 +${p.sell}</button></div>`).join('')}</div></section>`;}
function auction(){return `${title('FORMOSA AUCTION','寶島拍賣行',`<span class="badge">待設計</span>`)}<section class="auction-empty"><span>⚑</span><h2>好物，值得等一場好競標。</h2><p>未來將讓玩家上架物品、參與競標與收藏寶島好物。</p><div class="auction-roadmap"><b>物品上架</b><i>›</i><b>玩家競標</b><i>›</i><b>到期結標</b></div><p class="muted">競標規則、手續費、託管與交易保障尚待設計。<br>目前沒有上架或出價功能，也不會扣除資源。</p></section>`;}
function holdingsTotal(){return E.STOCKS.reduce((sum,s)=>sum+(state.holdings[s.id]?.qty||0)*state.market.prices[s.id]/100,0);}
function stocks(){const end=(state.market.hour+1)*E.HOUR;return `${title('FORMOSA STOCK EXCHANGE','寶島模擬股市',`<span class="badge">每小時更新</span>`)}<div class="market-summary"><div><small>可用遊戲新台幣</small><b>${money(state.cash)}</b></div><div><small>持股市值</small><b>${money(holdingsTotal())}</b></div><div><small>下一次行情更新</small><b data-until="${end}">${clock(end-Date.now())}</b></div></div><div class="market-notice">虛構公司與代號 · 本機規則模擬行情 · 每小時各股隨機 ±10% 內調整 · 與真實台股無關</div><div class="stock-table"><div class="stock-head"><span>股票 / 產業</span><span>成交價 / 漲跌</span><span>近 24 次走勢</span><span>持股 / 損益</span><span>交易</span></div>${E.STOCKS.map(s=>{const p=state.market.prices[s.id],hist=state.market.history[s.id],prev=hist.at(-2)||p,change=(p-prev)/prev*100,h=state.holdings[s.id]||{qty:0,costCents:0},profit=(h.qty*p-h.costCents)/100;return `<article class="stock-row"><div><b>${s.name}</b><small>${s.id} · ${s.sector}</small></div><div class="${change>=0?'stock-up':'stock-down'}"><b>${(p/100).toFixed(2)}</b><small>${change>=0?'▲':'▼'} ${Math.abs(change).toFixed(2)}%</small></div><canvas class="sparkline" data-stock-chart="${s.id}" width="170" height="55" aria-label="${s.name}歷史行情圖"></canvas><div><b>${money(h.qty)} 股</b><small class="${profit>=0?'stock-up':'stock-down'}">${profit>=0?'+':''}${money(profit)}</small></div><div class="trade-buttons"><button data-trade="${s.id}" data-side="buy">買進</button><button data-trade="${s.id}" data-side="sell" ${!h.qty?'disabled':''}>賣出</button></div></article>`;}).join('')}</div><div class="lottery-bottom"><section class="panel"><h3>交易說明</h3><p class="muted">紅漲綠跌，每 1 股為最小交易單位，1 張 = 1,000 股。以確認時的最新模擬成交價交易，無手續費、無放空。行情跨整點更新時須重新確認報價。價格下限 1、上限 100,000。</p></section><section class="panel"><h3>最近帳目</h3>${ledger(5)}</section></div>`;}
function charts(){document.querySelectorAll('[data-stock-chart]').forEach(c=>{const ctx=c.getContext('2d'),arr=state.market.history[c.dataset.stockChart];if(!ctx)return;const values=arr.length>1?arr:[arr[0],arr[0]],min=Math.min(...values),max=Math.max(...values),range=max-min||1;ctx.clearRect(0,0,170,55);ctx.strokeStyle=values.at(-1)>=values[0]?'#cd6456':'#349177';ctx.lineWidth=2;ctx.beginPath();values.forEach((v,i)=>{const x=5+i/(values.length-1)*160,y=45-(v-min)/range*35;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();});}
function render(){header();$('#nav').innerHTML=NAV.map(([id,i,n])=>`<button data-page="${id}" class="${page===id?'active':''}"><span>${i}</span>${n}${id==='auction'?'<em>籌備中</em>':''}</button>`).join('');$('#main').innerHTML=({home,jobs,tavern,shop,auction,stocks})[page]();if(page==='stocks')charts();}
function staminaModal(){modal(`<div class="eyebrow">TAKE A BREAK</div><h2>${icon('energy')} 體力補給站</h2><div class="stamina-number">${state.energy}<span> / 100</span></div><div class="progress"><i style="width:${state.energy}%"></i></div><p>每 5 分鐘恢復 1 點，離線也會恢復。工作開始時一次扣除整段所需體力。</p><div class="food-bag">${E.GOODS.map(g=>`<div><span>${g.icon} ${g.name} · +${g.energy}</span><button class="btn light" data-use="${g.id}" ${!state.food[g.id]||state.energy+g.energy>100?'disabled':''}>使用（${state.food[g.id]||0}）</button></div>`).join('')}</div><p class="muted">避免溢出：超過 100 的補給無法使用。</p><button class="btn gold" data-go-shop>到商店補貨 ›</button>`);}
function orderModal(id,side){const s=E.STOCKS.find(x=>x.id===id);if(!s)return;E.settle(state);order={id,side,price:state.market.prices[id]};modal(`<div class="eyebrow">SIMULATED ORDER</div><h2>${side==='buy'?'買進':'賣出'} ${s.name}</h2><p>${id} · 目前價格 <b>${(order.price/100).toFixed(2)}</b></p><form id="trade-form"><label class="field-label">股數（1 張 = 1,000 股）<input id="trade-qty" type="number" min="1" max="100000" step="1" value="1" required></label><div class="exchange-row"><span>交易金額</span><b id="order-total">${(order.price/100).toFixed(2)}</b></div><p class="muted">持有 ${state.holdings[id]?.qty||0} 股 · 可用 ${money(state.cash)} 新台幣</p><button class="btn gold full" type="submit">確認${side==='buy'?'買進':'賣出'}</button></form><p class="muted">僅為遊戲模擬交易，沒有連結證券帳戶。</p>`);}
function act(fn){try{fn();save();render();}catch(e){save();header();toast(e.message);}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.page){page=d.page;render();window.scrollTo(0,0);return;}if(d.game){tavernGame=d.game;render();return;}if(d.mode){bingoMode=d.mode;bingoNumbers=[];render();return;}if(d.number){const n=+d.number,arr=tavernGame==='bingo'?bingoNumbers:lottoNumbers,max=tavernGame==='bingo'?(bingoMode==='super'?1:10):6;if(arr.includes(n))arr.splice(arr.indexOf(n),1);else if(arr.length<max)arr.push(n);else return toast(`最多選 ${max} 個號碼`);arr.sort((a,b)=>a-b);render();return;}if(d.accept){const minutes=Number(document.querySelector(`[data-minutes="${d.accept}"]`).value);act(()=>{E.accept(state,d.accept,minutes);toast('工作開始，時間到會自動結算');});return;}if(d.region){cityRegion=d.region;mapModal();return;}if(d.mapCity){selectedCity=d.mapCity;mapModal(true);return;}if(d.joinCity){act(()=>joinCity(d.joinCity));return;}if(d.buy){act(()=>{E.buy(state,d.buy,1);toast('已放入背包，點使用可恢復體力');});return;}if(d.use){const opened=$('#modal').open;act(()=>{E.use(state,d.use);toast('補給完成，體力已恢復');if(opened)staminaModal();});return;}if(d.sell){act(()=>{E.sell(state,d.sell);toast('小物已售出，款項已入帳');});return;}if(d.sellPrize){act(()=>{E.sell(state,d.sellPrize,'prize');toast('紀念品已售出');});return;}if(d.trade){orderModal(d.trade,d.side);return;}if(d.goShop!==undefined){$('#modal').close();page='shop';render();return;}if(d.action){switch(d.action){case'choose':cityRegion='all';selectedCity=state.city||selectedCity;mapModal();break;case'stamina':staminaModal();break;case'next-jobs':act(()=>{E.finishNotice(state);page='jobs';});break;case'wallet':modal(`<h2>我的生活帳本</h2><p>${icon('cash')} 遊戲新台幣 ${money(state.cash)}</p>${ledger(15)}<p class="muted">不可兌現，與儲值黃金分開記錄。</p>`);break;case'gold':modal(`<h2>${icon('gold')} 黃金帳戶</h2><p>持有 ${state.premium} 黃金</p><p class="muted">儲值尚未串接。黃金不能投入酒館遊戲、兌換新台幣，或用於模擬股市。</p>`);break;case'quick-pick':if(tavernGame==='bingo')bingoNumbers=E.sample(80,bingoMode==='super'?1:5).sort((a,b)=>a-b);else lottoNumbers=E.sample(49,6).sort((a,b)=>a-b);render();break;case'place-ticket':act(()=>{E.bet(state,tavernGame,bingoMode,tavernGame==='bingo'?bingoNumbers:lottoNumbers,bingoStake);toast('已記錄，開獎後自動結算');});break;case'ichiban':act(()=>{const prize=E.ichiban(state);modal(`<div class="eyebrow">YOUR SOUVENIR</div><h2>${prize.name}</h2><div class="prize-reveal">${prize.icon}</div><p>已放入收藏背包，可保留或在商店以 ${prize.sell} 新台幣售出。</p><p class="muted">純遊戲紀念品，沒有實物或現金獎品。</p>`);});break;case'spin':if(spinning)return;act(()=>{E.slots(state);spinning=true;});if(spinning)setTimeout(()=>{spinning=false;if(page==='tavern')render();},850);break;}}});
document.addEventListener('change',e=>{if(e.target.id==='bingo-stake'){bingoStake=+e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='trade-qty'&&order){const qty=Number(e.target.value);$('#order-total').textContent=Number.isInteger(qty)&&qty>0?money(qty*order.price/100):'—';}});
document.addEventListener('submit',e=>{if(e.target.id!=='trade-form')return;e.preventDefault();act(()=>{E.settle(state);if(!order||state.market.prices[order.id]!==order.price)throw Error('行情已更新，請關閉後重新確認報價');const result=E.trade(state,order.id,order.side,Number($('#trade-qty').value));$('#modal').close();toast('交易完成，成交金額 '+money(result.total));});});
$('.close').onclick=()=>$('#modal').close();$('#help').onclick=()=>modal('<h2>新寶島生活指南</h2><p>找工作賺取新台幣，體力不足可購買補給。工作小物能在商店出售，也可使用遊戲資源參加酒館小遊戲、收藏一番賞紀念品與買賣虛構股票。</p><p>所有倒數依目前裝置時間；離線工作、已參加的開獎及行情會在再次開啟時結算。這是本機模擬，並非多人正式伺服器。</p><p class="muted">遊戲資源不可兌現，不連接真實彩券、金流或證券帳戶。拍賣行尚待設計。</p>');$('#profile').onclick=()=>modal(`<h2>寶島新居民</h2><p>家鄉：${state.city||'尚未選擇'}<br>社會歷練：${money(state.exp)}<br>納稅額度：${money(state.tax)}</p><p class="muted">本機生活模擬 · LINE 登入尚未連接</p>`);
let lastDraws=E.round('bingo').id+':'+E.round('lotto').id;
function tick(){const priorJob=!!state.job,priorEnergy=state.energy,priorHour=state.market.hour,priorTickets=state.tickets.filter(t=>t.status==='pending').length;E.settle(state);const draws=E.round('bingo').id+':'+E.round('lotto').id;const changed=(priorJob&&!state.job)||priorEnergy!==state.energy||priorHour!==state.market.hour||priorTickets!==state.tickets.filter(t=>t.status==='pending').length||draws!==lastDraws;if(changed){lastDraws=draws;save();if(!$('#modal').open)render();else header();}document.querySelectorAll('[data-until]').forEach(el=>el.textContent=clock(Number(el.dataset.until)-Date.now()));const bar=document.querySelector('[data-job-progress]');if(bar&&state.job)bar.style.width=Math.min(100,(Date.now()-state.job.start)/(state.job.end-state.job.start)*100)+'%';}
E.settle(state);save();render();setInterval(tick,1000);window.addEventListener('pagehide',save);
